const raw=await tools.exec_command({cmd:"Get-Content authoring-plar.txt -Raw",max_output_tokens:25000});const p=JSON.parse(raw.output);
p.sources.push({id:"authoring-update",path:"AUTHORING-UPDATE.md",sha256:"495c8450391dcb26191ec2c0ad02dc8542a58b712e4009f813c51c2169e74b58"});
const a=p.assets.find(a=>a.id==="queue.working");
a.requirements.push({property:"reduced_motion",value:"In reduced-motion mode use a stationary Working symbol distinct from Ready and Paused. Compare and define both consumer mappings before any revised request. Existing normal-motion four-frame timing remains scoped to the original route.",authority:"requirement",sources:["authoring-update"],reason:"Scoped caller update for this prospective authoring branch, not a changed requirement on accepted original production."});
a.requirements.push({property:"reduced_motion_mapping",value:"Unresolved: current shared descriptor always declares frames4; renderer time-selects frames and has no reduced-motion branch. Review fixed-frame selection versus separate stationary destination and both-consumer behavior before revising contracts.",authority:"observation",sources:["queue-view","renderer-view-mjs","authoring-update"],reason:"Actual source comparison; no guessed destination or consumer code changes."});
a.next="Resolve retained prepared Working intent through caller comparison; define branch-only stationary reduced-motion mapping and contract for both consumers before separately assigned revised preparation. Do not dispatch the old animation-only request.";
a.delivery.checks.push("For the authoring branch, review stationary reduced-motion Working mapping and live behavior in both consumers, including visual distinction from Ready and Paused. Mapping/contract and review remain unresolved; old animation acceptance does not apply.");
p.coverage.included.push("AUTHORING update: inspected shared statusCell/compactStatus descriptors and renderer paint/animate; no reduced-motion mapping currently exists. Retained prepared request and historical plan; no consumer/source edit or remote generation.");
p.coverage.unresolved.push("Authoring branch stationary reduced-motion Working mapping and contract need independent caller review; old prepared animation request blocked.");
text(await tools.mcp__pixl_local__pixl_plar_save({path:"authoring-plar.txt",expect:load("currentWorking").hash,document:p}));
const c=JSON.parse((await tools.mcp__pixl_local__pixl_plar_read({path:"authoring-plar.txt",asset_id:"queue.working"})).content[0].text);store("reconciledWorking",c);text({hash:c.hash,requirements_hash:c.requirements_hash,production:c.production.next_action});
text(await tools.exec_command({cmd:"Get-Content work/queue.ready-reassessment/request-review.json -TotalCount 75; Get-Content work/queue.ready-reassessment/candidate-plan.json -TotalCount 65",max_output_tokens:3000}));

